/// Тип источника кандидатов для движка.
enum Work {
    /// brute-force: раунды маски (для инкремента — по одной подмаске на длину).
    Mask(Vec<Vec<Vec<u8>>>),
    /// straight: строки словаря.
    Words(Vec<Vec<u8>>),
    /// combinator: пары двух словарей.
    Combo(Vec<Vec<u8>>, Vec<Vec<u8>>),
}

/// Чтение словаря: строки, обрезка \r, пропуск пустых.
fn read_wordlist(path: &Path) -> Result<Vec<Vec<u8>>, String> {
    let content = std::fs::read(path)
        .map_err(|e| format!("не удалось прочитать словарь {}: {}", path.display(), e))?;
    let mut out = Vec::new();
    for line in content.split(|&b| b == b'\n') {
        let line = line.strip_suffix(b"\r").unwrap_or(line);
        if line.is_empty() {
            continue;
        }
        out.push(line.to_vec());
    }
    Ok(out)
}

/// Чтение файла хешей. Формат строки: `hex` или `hex:метаданные` (суффикс игнорируется).
fn read_hash_file(path: &Path) -> Result<Vec<String>, String> {
    let content = std::fs::read_to_string(path)
        .map_err(|e| format!("не удалось прочитать файл хешей {}: {}", path.display(), e))?;
    let mut out = Vec::new();
    for line in content.lines() {
        let line = line.trim();
        if line.is_empty() {
            continue;
        }
        let hash_part = line.split(':').next().unwrap_or("").trim();
        if !hash_part.is_empty() {
            out.push(hash_part.to_string());
        }
    }
    Ok(out)
}

/// Главная точка входа крака. Возвращает число найденных.
pub fn run(cfg: &Config) -> Result<u32, String> {
    // 1. Цели.
    let mut hash_hexes: Vec<String> = cfg.hashes.clone();
    if let Some(hf) = &cfg.hash_file {
        hash_hexes.extend(read_hash_file(hf)?);
    }
    if hash_hexes.is_empty() {
        return Err("нет хешей для крака".to_string());
    }

    // Декодируем цели; ошибка hex — стоп.
    let mut targets: HashSet<Vec<u8>> = HashSet::new();
    for h in &hash_hexes {
        let raw = hex_decode(h).map_err(|e| format!("хеш '{}': {}", h, e))?;
        if raw.len() != digest_len(cfg.hash_type) {
            return Err(format!(
                "хеш '{}' имеет длину {} байт, а {} ожидает {} байт",
                h,
                raw.len(),
                cfg.hash_type.name(),
                digest_len(cfg.hash_type)
            ));
        }
        targets.insert(raw);
    }

    // 2. Potfile: не искать уже взломанное.
    if !cfg.no_potfile {
        let entries = potfile::read_potfile(&cfg.outfile)?;
        let cracked = potfile::cracked_set(&entries);
        let before = targets.len();
        targets.retain(|t| !cracked.contains(&hex_of(t)));
        let skipped = before - targets.len();
        if skipped > 0 && !cfg.quiet {
            eprintln!("[+] {} хеш(ей) уже в potfile, пропускаю", skipped);
        }
    }
    if targets.is_empty() {
        if !cfg.quiet {
            eprintln!("[*] Все хеши уже взломаны. Используйте --show для списка.");
        }
        return Ok(0);
    }

    // 3. Работа.
    let work = match cfg.attack {
        AttackMode::Straight => {
            let wl = cfg.wordlist.as_ref().expect("валидировано");
            let words = read_wordlist(wl)?;
            if words.is_empty() {
                return Err(format!("словарь {} пуст", wl.display()));
            }
            Work::Words(words)
        }
        AttackMode::Combinator => {
            let w1 = read_wordlist(cfg.wordlist.as_ref().expect("валидировано"))?;
            let w2 = read_wordlist(cfg.wordlist2.as_ref().expect("валидировано"))?;
            if w1.is_empty() || w2.is_empty() {
                return Err("один из словарей пуст".to_string());
            }
            Work::Combo(w1, w2)
        }
        AttackMode::BruteForce => {
            let mask_str = cfg.mask.as_ref().expect("валидировано");
            let customs = parse_customs(cfg)?;
            let positions = parse_mask(mask_str, &customs)?;
            if positions.is_empty() {
                return Err("маска пуста".to_string());
            }
            let rounds = if cfg.increment {
                crate::attack::mask_rounds(
                    &positions,
