#!/usr/bin/env -S uv run
"""
yescrack — yescrypt hash cracker (каждый пароль на экран)
Цель: whitepeach из /etc/shadow
Python 3.14+: ctypes libcrypt

Режимы:
  hybrid     — мутации имени пользователя (по умолчанию)
  bruteforce — маска hashcat-стиля (--mask, опц. --min-len/--max-len)
  dictionary — wordlist (--wordlist, опц. суффиксы --suffix)
"""
import argparse
import ctypes
import ctypes.util
import itertools
import pathlib
import signal
import sys
import time

TARGET_HASH = b"$y$j9T$J0t3Y1jniKoit2K73.Bzt0$AI8sg.A0aZ8x2hKDH.Rik2UDFTyrTesMKUm/LrewWR5"
USERNAME = "whitepeach"

lib_path = ctypes.util.find_library('crypt')
if not lib_path:
    print("[-] libcrypt not found", file=sys.stderr)
    sys.exit(1)
_lib = ctypes.CDLL(lib_path)
_lib.crypt.argtypes = [ctypes.c_char_p, ctypes.c_char_p]
_lib.crypt.restype = ctypes.c_char_p


def check(pwd: str) -> bool:
    try:
        return _lib.crypt(pwd.encode(), TARGET_HASH) == TARGET_HASH
    except KeyboardInterrupt:
        raise
    except Exception:
        return False


def gen():
    seen = set()
    cl = []
    def add(p):
        if p not in seen and len(p)>=1: seen.add(p); cl.append(p)
    base = USERNAME.lower()
    for v in [USERNAME, base, base.capitalize(), USERNAME.upper(), base.title()]: add(v)
    for s in ['','1','123','1234','12345','!','@','#','2024','2025','2026','0','00','69','007','1!','123!','.','..','...','99','777','42']:
        add(base+s); add(base.capitalize()+s); add(base.upper()+s)
    for p in ['password','password123','admin','root','qwerty','123456','12345678','letmein','welcome','monkey','dragon','master','sunshine','princess','football','iloveyou','trustno1','hunter','ranger','peach','peach123', '2515Fbi3', '2515Fbi345']: add(p)
    for w in ['white','White','WHITE','whit3','Wh1t3']:
        for p in ['peach','Peach','PEACH','p34ch','P34ch']:
            add(w+p); add(w+'_'+p); add(w+'-'+p); add(p+w)
    leet = {'a':'4','e':'3','i':'1','o':'0','s':'5','t':'7'}
    for word in list(seen):
        for orig, repl in leet.items():
            if orig in word: add(word.replace(orig, repl))
    for word in list(seen):
        if len(word)>4: add(word[::-1])
    for word in list(seen):
        add(word*2); add(word.upper()+word); add(word+word.upper())
    for y in ['2020','2021','2022','2023','2024','2025','2026']:
        for word in list(seen):
            add(word+y); add(y+word)
    return cl


# ── Маска hashcat-стиля ──────────────────────────────────────────────
_MASK_SETS = {
    'l': 'abcdefghijklmnopqrstuvwxyz',
    'u': 'ABCDEFGHIJKLMNOPQRSTUVWXYZ',
    'd': '0123456789',
    's': '!@#$%^&*()-_=+[]{};:,.<>?/',
    'a': 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789!@#$%^&*()-_=+[]{};:,.<>?/',
}


def parse_mask(mask: str):
    """Разобрать маску в список наборов символов (по позиции). ?l/?u/?d/?s/?a, остальное — литералы."""
    positions = []
    i = 0
    while i < len(mask):
        ch = mask[i]
        if ch == '?' and i + 1 < len(mask) and mask[i + 1] in _MASK_SETS:
            positions.append(_MASK_SETS[mask[i + 1]])
            i += 2
        else:
            positions.append(ch)
            i += 1
    return positions


def bruteforce_candidates(positions, min_len, max_len):
    """Инкремент длин от min до max; для длины < длины маски — первые N позиций."""
    for length in range(min_len, max_len + 1):
        for combo in itertools.product(*positions[:length]):
            yield ''.join(combo)


def bruteforce_total(positions, min_len, max_len):
    total = 0
    for length in range(min_len, max_len + 1):
        n = 1
        for charset in positions[:length]:
            n *= len(charset)
        total += n
    return total


# ── Словарь ──────────────────────────────────────────────────────────
def load_wordlist(path):
    words = []
    for line in pathlib.Path(path).read_text(encoding='utf-8', errors='replace').splitlines():
        w = line.rstrip('\r')
        if w:
            words.append(w)
    return words


def dict_candidates(words, suffixes):
    if suffixes:
        for w in words:
            for s in suffixes:
                yield w + s
    else:
        yield from words


# ── Общий цикл перебора ──────────────────────────────────────────────
def run_candidates(candidates, total):
    t0 = time.time()
    i = 0
    try:
        for i, pwd in enumerate(candidates, 1):
            ok = check(pwd)
            elapsed = time.time() - t0
            status = "✅" if ok else "❌"
            print(f"[{i:>6}/{total:,}] {status} {pwd}")
            sys.stdout.flush()
            if ok:
                print(f"\n{'='*60}", file=sys.stderr)
                print(f"✅ ПАРОЛЬ НАЙДЕН: {pwd}", file=sys.stderr)
                print(f"   Попыток: {i:,} за {elapsed:.1f}с", file=sys.stderr)
                print(f"{'='*60}", file=sys.stderr)
                print(pwd, end='')
                sys.exit(0)
        elapsed = time.time() - t0
        print(f"{'─'*60}", file=sys.stderr)
        print(f"[-] Не найден. {i:,} попыток за {elapsed:.1f}с", file=sys.stderr)
    except KeyboardInterrupt:
        elapsed = time.time() - t0
        print(f"\n{'─'*60}", file=sys.stderr)
        print(f"[!] Прервано (Ctrl+C). Успел перебрать {i:,}/{total:,} за {elapsed:.1f}с", file=sys.stderr)
        sys.exit(130)


if __name__ == '__main__':
    parser = argparse.ArgumentParser(
        prog='crack.py',
        description='yescrack — yescrypt hash cracker (dictionary / bruteforce / hybrid)',
        formatter_class=argparse.RawDescriptionHelpFormatter,
        epilog=(
            "Режимы (приоритет):\n"
            "  --mask [--min-len N --max-len N]  → брутфорс по маске hashcat-стиля\n"
            "  --wordlist [--suffix S]           → словарь (+ суффиксы через запятую)\n"
            "  (без флагов)                      → гибрид: мутации имени пользователя\n"
            "\n"
            "Маска hashcat-стиля: ?l (a-z), ?u (A-Z), ?d (0-9), ?s (спецсимволы),\n"
            "?a (l+u+d+s), остальные символы — литералы. Пример: --mask '?u?l?l?d'\n"
        ),
    )
    parser.add_argument('--hash', default='$y$j9T$J0t3Y1jniKoit2K73.Bzt0$AI8sg.A0aZ8x2hKDH.Rik2UDFTyrTesMKUm/LrewWR5',
                        help='целевой yescrypt-хеш (default: встроенный)')
    parser.add_argument('--user', default='whitepeach',
                        help='имя пользователя для гибридного генератора (default: whitepeach)')
    parser.add_argument('--mask', default=None,
                        help='маска перебора hashcat-стиля: ?l ?u ?d ?s ?a, остальное — литералы')
