## 1. Новый файл src/yescrypt.rs — создай ровно этот код:
```rust
//! Проверка yescrypt ($y$...) через FFI к libxcrypt (crypt_r, thread-safe).

use std::ffi::CString;
use std::os::raw::c_char;

/// struct crypt_data из libxcrypt: 32768 байт, занулённый (initialized = 0).
#[repr(C, align(8))]
pub struct CryptData {
    buf: [u8; 32768],
}

impl CryptData {
    pub fn new() -> Self {
        CryptData { buf: [0u8; 32768] }
    }
}

#[link(name = "crypt")]
unsafe extern "C" {
    fn crypt_r(
        phrase: *const c_char,
        setting: *const c_char,
        data: *mut CryptData,
    ) -> *const c_char;
}

/// Проверка: crypt_r(pw, setting) == setting. Потокобезопасна при своём data на поток.
pub fn yescrypt_verify(pw: &[u8], setting: &str, data: &mut CryptData) -> bool {
    let Ok(pw_c) = CString::new(pw) else { return false; };
    let Ok(set_c) = CString::new(setting) else { return false; };
    let res = unsafe { crypt_r(pw_c.as_ptr(), set_c.as_ptr(), data as *mut CryptData) };
    if res.is_null() { return false; }
    let out = unsafe { std::ffi::CStr::from_ptr(res) };
    let Ok(out_s) = out.to_str() else { return false; };
    out_s == setting
}
```

